// ProjectServiceHandler is an implementation of the codefoundry.v1.ProjectService service.
type ProjectServiceHandler interface {
	// Register adds a project by path. A path inside a git repository registers that
	// repository (its main worktree); any other existing directory registers as a
	// project without git (Project.git false).
	Register(context.Context, *connect.Request[v1.RegisterProjectRequest]) (*connect.Response[v1.RegisterProjectResponse], error)
	// InspectFolder says what Register would make of a folder before the Add Project
	// dialog adds it: whether it is (or is inside) a git repository, and, when it is not,
	// the git repositories directly inside it (immediate children with a .git directory or
	// file; hidden and symlinked children are skipped), sorted by name. A folder of repos
	// can be added as a rooted workspace instead (the project.add-workspace command).
	// InvalidArgument for a path Register would refuse (outside home, not a directory).
	InspectFolder(context.Context, *connect.Request[v1.InspectFolderRequest]) (*connect.Response[v1.InspectFolderResponse], error)
	// Unregister forgets a project. Worktrees on disk are not touched.
	Unregister(context.Context, *connect.Request[v1.UnregisterProjectRequest]) (*connect.Response[v1.UnregisterProjectResponse], error)
	// List returns registered projects with their worktrees.
	List(context.Context, *connect.Request[v1.ListProjectsRequest]) (*connect.Response[v1.ListProjectsResponse], error)
	// Get returns one project.
	Get(context.Context, *connect.Request[v1.GetProjectRequest]) (*connect.Response[v1.GetProjectResponse], error)
	// CreateWorktree creates a worktree with a new or existing branch.
	CreateWorktree(context.Context, *connect.Request[v1.CreateWorktreeRequest]) (*connect.Response[v1.CreateWorktreeResponse], error)
	// RemoveWorktree removes a worktree (and optionally its branch). Without force it is
	// refused while a live thread, a running terminal or a workspace holds it (the
	// cleanup rule's non-git half).
	RemoveWorktree(context.Context, *connect.Request[v1.RemoveWorktreeRequest]) (*connect.Response[v1.RemoveWorktreeResponse], error)
	// DeleteBranch deletes a local branch no worktree has checked out (and optionally
	// origin's), for a branch whose worktree is already gone.
	DeleteBranch(context.Context, *connect.Request[v1.DeleteBranchRequest]) (*connect.Response[v1.DeleteBranchResponse], error)
	// CleanupWorktrees removes worktrees whose work is already in the default branch:
	// merged_clean (which includes "made by Code Foundry"), and no live thread, running
	// terminal or workspace holds them. It
	// refreshes the project's status first (a caller wanting fresh remote refs fetches
	// before), re-evaluates, and removes with `git worktree remove` (never --force).
	// Branches are never deleted. dry_run only evaluates the current snapshot.
	CleanupWorktrees(context.Context, *connect.Request[v1.CleanupWorktreesRequest]) (*connect.Response[v1.CleanupWorktreesResponse], error)
	// Refresh forces a status reconcile for a project (or all projects when id is empty).
	Refresh(context.Context, *connect.Request[v1.RefreshProjectRequest]) (*connect.Response[v1.RefreshProjectResponse], error)
	// Watch streams project and worktree changes.
	Watch(context.Context, *connect.Request[v1.WatchProjectsRequest], *connect.ServerStream[v1.ProjectEvent]) error
	// GetWorktreeDetail returns the files changed and commits on a worktree against its
	// base (status.base_ref, else the local default branch). It computes on first call
	// (or after 10 idle minutes) and serves the cached result otherwise. While a
	// worktree has been asked about in the last 10 minutes, every status refresh of it
	// recomputes the detail and announces changes as worktree_detail_updated.
	GetWorktreeDetail(context.Context, *connect.Request[v1.GetWorktreeDetailRequest]) (*connect.Response[v1.GetWorktreeDetailResponse], error)
	// GetWorktreeFileDiff returns both sides of one file of a worktree for a diff view,
	// against the same base and merge base GetWorktreeDetail uses. WORKING: the merge
	// base's version against the file on disk (untracked files included); a worktree
	// without a base compares with HEAD (the empty tree on an unborn branch), as the
	// detail's file list does. BRANCH: the merge base's version against HEAD's; without
	// a base, error says so. Each side is at most 1 MiB. Computed on every call (not
	// cached); NotFound for an unknown worktree, InvalidArgument for a file path that
	// leaves the worktree, FailedPrecondition for a project without git.
	GetWorktreeFileDiff(context.Context, *connect.Request[v1.GetWorktreeFileDiffRequest]) (*connect.Response[v1.GetWorktreeFileDiffResponse], error)
	// ListRefs returns the refs a worktree can be based on: local branches and
	// remote-tracking branches (origin/<name>), the branch names by recency, plus the
	// default branch.
	ListRefs(context.Context, *connect.Request[v1.ListRefsRequest]) (*connect.Response[v1.ListRefsResponse], error)
	// InitGit turns a project without git into a git repository: `git init -b
	// <init.defaultBranch, else main>`, an empty "Initial commit", then a refresh.
	// FailedPrecondition when the project is already a git repository.
	InitGit(context.Context, *connect.Request[v1.InitGitRequest]) (*connect.Response[v1.InitGitResponse], error)
	// SearchGitHub searches github.com repositories with GitHub's search syntax and
	// returns the first 20 matches, best match first. The Add Project dialog sends it on
	// Enter, never per keystroke. InvalidArgument for an empty query.
	SearchGitHub(context.Context, *connect.Request[v1.SearchGitHubRequest]) (*connect.Response[v1.SearchGitHubResponse], error)
	// LookupGitHub returns one github.com repository. NotFound when it does not exist or
	// the viewer cannot see it.
	LookupGitHub(context.Context, *connect.Request[v1.LookupGitHubRequest]) (*connect.Response[v1.LookupGitHubResponse], error)
	// Clone runs `gh repo clone <owner>/<name> <config home>/projects/<owner>/<name> --
	// --progress` (the user's gh login and protocol apply), streams its output as
	// progress events, registers the clone and ends with a project event. AlreadyExists when
	// the destination exists; NotFound when GitHub has no such repository; other failures
	// carry gh's last lines. Bounded at 15 minutes. Cancelling the stream kills the clone
	// and removes what it wrote.
	Clone(context.Context, *connect.Request[v1.CloneProjectRequest], *connect.ServerStream[v1.CloneProjectEvent]) error
	// Create starts a new project at <config home>/projects/<name>: mkdir, `git init -b
	// <init.defaultBranch, else main>`, an empty "Initial commit", then registers it.
	// InvalidArgument for a name that is empty, starts with ".", or has anything but
	// letters, digits, "-", "_" and "."; AlreadyExists when the folder exists.
	Create(context.Context, *connect.Request[v1.CreateProjectRequest]) (*connect.Response[v1.CreateProjectResponse], error)
	// ListPublishOwners lists where the viewer can publish a repository: their own
	// account (public and private) and every organization they belong to that lets them
	// create repositories (GitHub's viewerCanCreateRepositories), with the visibilities
	// the organization lets members create when GitHub says (it tells only org owners).
	// Cached for 10 minutes in memory and on disk; allow_stale serves an older list.
	ListPublishOwners(context.Context, *connect.Request[v1.ListPublishOwnersRequest]) (*connect.Response[v1.ListPublishOwnersResponse], error)
	// Publish creates <owner>/<name> on GitHub from a git project without an origin
	// remote: `gh repo create <owner>/<name> --source <path> --remote origin --push
	// --<visibility>`, then refreshes the project. FailedPrecondition when the project is
	// not git or already has origin; a gh failure carries gh's last lines verbatim.
	// Bounded at 5 minutes.
	Publish(context.Context, *connect.Request[v1.PublishProjectRequest]) (*connect.Response[v1.PublishProjectResponse], error)
	// Delete unregisters a project made by Create and removes its folder from disk. Only
	// a project directly inside the projects directory can be deleted (FailedPrecondition
	// otherwise); nothing on GitHub is touched. The Add Project dialog calls it when a
	// new project is cancelled before it is kept or published.
	Delete(context.Context, *connect.Request[v1.DeleteProjectRequest]) (*connect.Response[v1.DeleteProjectResponse], error)
}

// NewProjectServiceHandler builds an HTTP handler from the service implementation. It returns the
// path on which to mount the handler and the handler itself.
//
// By default, handlers support the Connect, gRPC, and gRPC-Web protocols with the binary Protobuf
// and JSON codecs. They also support gzip compression.
